/* generateur des piles de maquettes : reconstruit les cartes exactement
   comme le balisage d'origine (le module realisations et l'apercu lisent
   ces attributs). Execution immediate, le script precede les modules. */
(function(){
  var piles = document.querySelectorAll('.rl-pile[data-reals="sites"]');
  if (!piles.length || !window.DGZ_REALS.sites.length) return;
  var L = window.DGZ_REALS.sites;
  for (var k = 0; k < piles.length; k++){
    var html = '';
    for (var i = 0; i < L.length; i++){
      var p = L[i], actif = (i === 0);
      html += '<a class="rl-shot' + (actif ? ' is-actif' : '') + '" data-i="' + i +
        '" style="--r:' + p.r + '" data-apercu-carte data-apercu' +
        (p.embed === false ? '' : ' data-apercu-embed') +
        ' data-logo="' + p.logo + '" href="' + p.href + '" target="_blank" rel="noopener"' +
        ' data-nom="' + p.nom + '" data-sec="' + p.sec + '" data-res="' + (p.res || '') + '"' +
        ' aria-label="Aper\u00e7u du site ' + p.nom + '"' +
        (actif ? '' : ' tabindex="-1" aria-hidden="true"') + '>' +
        '<span class="rl-bar" aria-hidden="true"><i></i><i></i><i></i></span>' +
        '<img src="' + p.img + '" alt="' + p.alt + '" width="720" height="506" loading="' +
        (actif ? 'eager' : 'lazy') + '" decoding="async" draggable="false">' +
        '<span class="rl-loupe" aria-hidden="true">Aper\u00e7u</span>' +
        '<span class="rl-ctx" hidden><span data-apercu-tag>Site web</span>' +
        '<span data-apercu-titre>' + p.nom + '</span>' +
        '<span data-apercu-meta>' + p.sec + '</span></span></a>';
    }
    piles[k].innerHTML = html;
  }
})();

/* generateur des scenes de contenus community (.rl-stage[data-reals="contenus"]) :
   4 gabarits (reel, post, carrousel, LinkedIn), SVG identiques a l'original.
   type carr : pastille 1/N et points deduits du nombre de medias. */
(function(){
  var stages = document.querySelectorAll('[data-reals="contenus"]');
  var L = window.DGZ_REALS.contenus || [];
  if (!stages.length || !L.length) return;
  var COEUR = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.4s-7.4-4.6-9.4-9C1.2 8.3 2.8 5.4 5.8 5.1c1.9-.2 3.6.8 4.6 2.4a5 5 0 0 1 .8 1.4l.8-1.4c1-1.6 2.7-2.6 4.6-2.4 3 .3 4.6 3.2 3.2 6.3-2 4.4-9.4 9-9.4 9z" fill="none"/></svg>';
  var BULLE = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.6 12A8.6 8.6 0 1 1 12 3.4 8.6 8.6 0 0 1 20.6 12z"/><path d="M6.8 20.2 4.6 21l.8-2.4"/></svg>';
  var AVION = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.4 3.6 3.8 10.2l6.4 2.6 2.6 6.4z"/><path d="M20.4 3.6 10.2 12.8"/></svg>';
  var MARQUE = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6.4 3.6h11.2v16.8L12 16.6l-5.6 3.8z"/></svg>';
  var ACTIONS = '<div class="rlc-actions" aria-hidden="true"><span class="rlc-ico">' + COEUR +
    '</span><span class="rlc-ico">' + BULLE + '</span><span class="rlc-ico">' + AVION +
    '</span><span class="rlc-ico rlc-book">' + MARQUE + '</span></div>';
  var REELIC = '<span class="rlc-reelic" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="2.8" y="2.8" width="18.4" height="18.4" rx="4.6"/><path d="M2.8 8h18.4M8.4 2.8 11.6 8M14.4 2.8 17.6 8"/><path d="M10.2 11.6l4.8 2.9-4.8 2.9z"/></svg></span>';
  var PLAY = '<span class="rlc-play" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8.6 5.8l10 6.2-10 6.2z"/></svg></span>';
  function carte(p){
    var morceaux = p.medias.split('|');
    var premiere = morceaux[0].replace(/^(img|vid):/, '');
    var tete = '<div class="rlc rlc--' + p.type + ' csx-crea" role="button" tabindex="0" data-medias="' +
      p.medias + '" data-alt="' + p.alt + '">';
    var likes = p.likes ? '<p class="rlc-likes" aria-hidden="true"><b>' + p.likes + '</b> J\u2019aime</p>' : '';
    if (p.type === 'reel')
      return tete + '<div class="rlc-media"><img src="' + p.poster + '" alt="" loading="lazy" decoding="async">' +
        REELIC + PLAY + '<div class="rlc-pied" aria-hidden="true"><i class="rlc-ava">' + p.ava +
        '</i><b>' + p.handle + '</b></div></div></div>';
    if (p.type === 'li')
      return tete + '<div class="rlc-head" aria-hidden="true"><i class="rlc-ava rlc-ava--sq">' + p.ava +
        '</i><span class="rlc-idl"><b>' + p.handle + '</b><em>Publication \u00b7 LinkedIn</em></span><span class="rlc-dots">\u22ef</span></div>' +
        '<div class="rlc-media"><img src="' + premiere + '" alt="" loading="lazy" decoding="async"></div>' +
        '<div class="rlc-libar" aria-hidden="true"><span>J\u2019aime</span><span>Commenter</span><span>Partager</span></div></div>';
    var pastille = (p.type === 'carr') ? '<span class="rlc-pill" aria-hidden="true">1/' + morceaux.length + '</span>' : '';
    var points = '';
    if (p.type === 'carr'){
      points = '<div class="rlc-cdots" aria-hidden="true">';
      for (var i = 0; i < morceaux.length; i++) points += (i ? '<i></i>' : '<i class="on"></i>');
      points += '</div>';
    }
    return tete + '<div class="rlc-head" aria-hidden="true"><i class="rlc-ava">' + p.ava + '</i><b>' +
      p.handle + '</b><span class="rlc-dots">\u22ef</span></div>' +
      '<div class="rlc-media"><img src="' + premiere + '" alt="" loading="lazy" decoding="async">' + pastille +
      '</div>' + points + ACTIONS + likes + '</div>';
  }
  for (var k = 0; k < stages.length; k++){
    var html = '';
    for (var i = 0; i < L.length; i++) html += carte(L[i]);
    stages[k].innerHTML = html;
  }
})();

/* generateur des carrousels de cas clients (.cas-stage[data-reals]) :
   injection verbatim des articles ; le module generique .cas-frame et le
   popup de detail (casPop) les prennent en charge ensuite. */
(function(){
  var CLES = {'cas-meta': 'casMeta', 'cas-sea': 'casSea', 'cas-seo': 'casSeo'};
  for (var attr in CLES){
    var L = window.DGZ_REALS[CLES[attr]] || [];
    var hotes = document.querySelectorAll('[data-reals="' + attr + '"]');
    if (!L.length || !hotes.length) continue;
    for (var k = 0; k < hotes.length; k++) hotes[k].innerHTML = L.join('');
  }
})();
